:root{--ink: #1b1f24; --ink-soft: #3f4850; --ink-mute: #556069; --line: #c7cfd7; --line-soft: #e3e8ed; --bg: #f4f6f8; --surface: #ffffff; --accent: #1b4ed8; --accent-dark: #123a9e; --radius: 3px;}
*, ::before, ::after{box-sizing: border-box;}
body{margin: 0px; background: var(--bg); color: var(--ink); font-family: "Segoe UI", "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", Arial, sans-serif; font-size: 16px; line-height: 1.7; font-variant-numeric: tabular-nums;}
img{max-width: 100%; height: auto; display: block;}
figure{margin: 0px;}
p{margin: 0px 0px 14px;}
a{color: var(--accent);}
h1, h2, h3{letter-spacing: 0.01em;}
:focus-visible{outline: 2px solid var(--accent); outline-offset: 2px;}
.wrap{width: 100%; max-width: 1120px; margin: 0px auto; padding-left: 24px; padding-right: 24px;}
.site-header{background: var(--surface); border-bottom: 1px solid var(--line);}
.header-inner{display: flex; align-items: center; gap: 32px; min-height: 64px; padding-top: 8px; padding-bottom: 8px;}
.brand{font-size: 18px; font-weight: 700; color: var(--ink); text-decoration: none; white-space: nowrap;}
.site-nav{display: flex; gap: 24px; font-size: 15px;}
.site-nav a{color: var(--ink-soft); text-decoration: none; padding: 4px 0px; border-bottom: 2px solid transparent;}
.site-nav a:hover{color: var(--ink); border-bottom-color: var(--accent);}
.header-cta{margin-left: auto;}
.btn{display: inline-block; font-size: 15px; font-weight: 600; line-height: 1.4; padding: 11px 20px; border: 1px solid var(--accent); background: var(--accent); color: rgb(255, 255, 255); text-decoration: none; border-radius: var(--radius);}
.btn:hover{background: var(--accent-dark); border-color: var(--accent-dark);}
.hero{background: var(--surface); border-bottom: 1px solid var(--line);}
.hero-grid{display: grid; grid-template-columns: minmax(0px, 1fr) minmax(0px, 420px); gap: 48px; align-items: center; padding-top: 48px; padding-bottom: 48px;}
.hero h1{font-size: clamp(28px, 3.4vw, 42px); line-height: 1.2; margin: 0px 0px 14px;}
.hero-lead{font-size: 19px; color: var(--ink-soft); margin: 0px 0px 18px;}
.hero-notes{list-style: none; margin: 0px 0px 26px; padding: 0px; font-size: 15px; color: var(--ink-soft);}
.hero-notes li{padding-left: 14px; border-left: 2px solid var(--line);}
.hero-notes li + li{margin-top: 8px;}
.hero-figure img{width: 100%; height: 340px; object-fit: cover; background: rgb(227, 232, 237); border: 1px solid var(--line); border-radius: var(--radius);}
.page-head{background: var(--surface); border-bottom: 1px solid var(--line); padding-top: 40px; padding-bottom: 40px;}
.page-head h1{font-size: clamp(26px, 3vw, 36px); margin: 0px 0px 12px;}
.page-lead{font-size: 17px; color: var(--ink-soft); max-width: 36em; margin: 0px 0px 22px;}
.section{padding-top: 48px; padding-bottom: 48px; border-bottom: 1px solid var(--line-soft);}
.section h2{font-size: 22px; margin: 0px 0px 10px;}
.section-note{font-size: 15px; color: var(--ink-mute); max-width: 38em; margin: 0px 0px 24px;}
.prose{max-width: 38em;}
.prose p:last-child{margin-bottom: 0px;}
.prod-list{display: grid; grid-template-columns: repeat(2, minmax(0px, 1fr)); gap: 0px 48px; border-top: 1px solid var(--line);}
.prod{padding: 22px 0px 24px; border-bottom: 1px solid var(--line-soft);}
.prod h3{font-size: 17px; margin: 0px 0px 12px;}
.mini-spec{display: grid; grid-template-columns: auto minmax(0px, 1fr); gap: 6px 18px; margin: 0px 0px 14px; font-size: 15px;}
.mini-spec dt{color: var(--ink-mute); white-space: nowrap;}
.mini-spec dd{margin: 0px; font-weight: 600;}
.link-more{font-size: 15px; color: var(--accent); text-decoration: none; border-bottom: 1px solid var(--accent); padding-bottom: 2px;}
.link-more:hover{color: var(--accent-dark); border-bottom-color: var(--accent-dark);}
.cap-grid{list-style: none; margin: 0px; padding: 18px 0px; display: grid; grid-template-columns: repeat(4, minmax(0px, 1fr)); gap: 12px 24px; border-top: 1px solid var(--line); border-bottom: 1px solid var(--line);}
.cap-grid li{font-weight: 600; font-size: 16px;}
.wide-figure{margin-bottom: 28px;}
.wide-figure img{width: 100%; height: 300px; object-fit: cover; background: rgb(227, 232, 237); border: 1px solid var(--line); border-radius: var(--radius);}
.industry-list{list-style: none; margin: 0px; padding: 0px; display: grid; grid-template-columns: repeat(4, minmax(0px, 1fr)); gap: 16px 24px;}
.industry-list li{border-left: 3px solid var(--accent); padding-left: 12px; font-size: 16px; font-weight: 600;}
.facts{display: grid; grid-template-columns: auto minmax(0px, 1fr); gap: 10px 24px; margin: 0px; font-size: 15px;}
.facts dt{color: var(--ink-mute); white-space: nowrap;}
.facts dd{margin: 0px; font-weight: 600; overflow-wrap: anywhere;}
.side-grid{display: grid; grid-template-columns: minmax(0px, 1fr) minmax(0px, 380px); gap: 48px; align-items: start;}
.side-figure img{width: 100%; height: 300px; object-fit: cover; background: rgb(227, 232, 237); border: 1px solid var(--line); border-radius: var(--radius);}
.table-wrap{border: 1px solid var(--line); border-radius: var(--radius); background: var(--surface); overflow: hidden;}
.table-narrow{max-width: 660px;}
.spec-table{width: 100%; border-collapse: collapse; font-size: 15px;}
.spec-table caption{text-align: left; font-size: 13px; color: var(--ink-mute); padding: 14px 16px 0px;}
.spec-table th, .spec-table td{padding: 12px 16px; text-align: left; vertical-align: top; border-bottom: 1px solid var(--line-soft);}
.spec-table tbody tr:last-child th, .spec-table tbody tr:last-child td{border-bottom: 0px;}
.spec-table th[scope="row"]{width: 42%; font-weight: 500; color: var(--ink-soft); background: rgb(247, 249, 250);}
.spec-table td{font-weight: 600;}
.cap-list{list-style: none; margin: 0px; padding: 0px; max-width: 640px;}
.cap-list li{padding: 14px 0px 14px 16px; border-left: 2px solid var(--line); border-bottom: 1px solid var(--line-soft); font-weight: 600; font-size: 16px;}
.cap-list li:first-child{border-top: 1px solid var(--line-soft);}
.contact-grid{display: grid; grid-template-columns: minmax(0px, 1fr) minmax(0px, 1fr); gap: 48px; align-items: start;}
.contact-note h2{font-size: 18px; margin: 0px 0px 10px;}
.contact-note p{max-width: 32em; color: var(--ink-soft); margin: 0px;}
[data-system-inquiry]{background: var(--surface); border: 1px solid var(--line); border-radius: var(--radius); padding: 24px; max-width: 720px;}
.site-footer{background: rgb(27, 31, 36); color: rgb(228, 233, 237); padding: 40px 0px 20px; font-size: 15px;}
.footer-inner{display: grid; grid-template-columns: minmax(0px, 1.3fr) minmax(0px, 0.8fr) minmax(0px, 1.3fr); gap: 32px;}
.footer-name{font-size: 17px; font-weight: 700; margin: 0px 0px 8px; color: rgb(255, 255, 255);}
.footer-text{margin: 0px; color: rgb(194, 202, 210); max-width: 30em;}
.footer-nav{display: flex; flex-wrap: wrap; gap: 8px 20px; align-content: start;}
.footer-nav a{color: rgb(228, 233, 237); text-decoration: none;}
.footer-nav a:hover{text-decoration: underline;}
.footer-contact p{margin: 0px 0px 8px; color: rgb(194, 202, 210); overflow-wrap: anywhere;}
.footer-base{margin-top: 28px; padding-top: 16px; border-top: 1px solid rgb(51, 58, 66); font-size: 13px; color: rgb(169, 178, 187);}
.footer-base p{margin: 0px;}
@media (max-width: 900px){.side-grid{grid-template-columns: minmax(0px, 1fr); gap: 32px;}
.contact-grid{grid-template-columns: minmax(0px, 1fr); gap: 32px;}
.footer-inner{grid-template-columns: minmax(0px, 1fr); gap: 24px;}}
@media (max-width: 768px){.header-inner{flex-wrap: wrap; gap: 10px 18px; padding-top: 10px; padding-bottom: 10px;}
.brand{flex: 1 1 100%;}
.header-cta{margin-left: auto; padding: 9px 14px; font-size: 14px;}
.hero-grid{grid-template-columns: minmax(0px, 1fr); gap: 28px; padding-top: 32px; padding-bottom: 32px;}
.hero-figure img{height: 240px;}
.prod-list{grid-template-columns: minmax(0px, 1fr); gap: 0px;}
.cap-grid{grid-template-columns: repeat(2, minmax(0px, 1fr));}
.industry-list{grid-template-columns: repeat(2, minmax(0px, 1fr));}
.wide-figure img{height: 220px;}
.section{padding-top: 36px; padding-bottom: 36px;}
.facts{display: block;}
.facts dt{margin-top: 12px;}
.facts dd{margin: 2px 0px 0px;}
.facts dt:first-child{margin-top: 0px;}}
@media (max-width: 520px){.site-nav{flex: 1 1 100%;}
.header-cta{flex: 1 1 100%; text-align: center;}}
